<script lang="ts">
  import { onMount } from 'svelte';
  import { api } from '$lib/api';
  type Achievement = { achievementId: number; name: string; description: string; iconName: string; isActive: boolean; awardCount: number };
  type Mission = { missionId: number; title: string; description: string; category: string; isActive: boolean; completionCount: number };
  type Rank = { rankId: number; name: string; sortOrder: number; displayColor?: string | null; isActive: boolean; studentCount: number };
  type Student = { studentId: number; displayName: string; rankName?: string | null; status: string };
  let achievements: Achievement[] = []; let missions: Mission[] = []; let ranks: Rank[] = []; let students: Student[] = [];
  let achievementForm = { name: '', description: '', iconName: 'star' }; let missionForm = { title: '', description: '', category: 'Training' }; let rankForm = { name: '', displayColor: '#d9a245' }; let rankAssignment = { studentId: '', rankId: '', awardedDate: new Date().toISOString().slice(0, 10), notes: '' };
  let loading = true; let busy = ''; let error = ''; let notice = '';
  async function load() { loading = true; error = ''; try { [achievements, missions, ranks, students] = await Promise.all([api<Achievement[]>('/api/portal-admin/configuration/achievements'), api<Mission[]>('/api/portal-admin/configuration/missions'), api<Rank[]>('/api/portal-admin/configuration/ranks'), api<Student[]>('/api/portal-admin/students')]); } catch (e) { error = e instanceof Error ? e.message : 'Could not load portal configuration.'; } finally { loading = false; } }
  async function create(path: string, payload: unknown, success: string, reset: () => void) { busy = path; error = ''; notice = ''; try { await api(path, { method: 'POST', body: JSON.stringify(payload) }); reset(); notice = success; await load(); } catch (e) { error = e instanceof Error ? e.message : 'Could not save configuration.'; } finally { busy = ''; } }
  async function toggle(path: string, active: boolean, label: string) { const endpoint = path.startsWith('/ranks/') ? `/api/portal-admin/configuration${path}` : path; busy = path; error = ''; notice = ''; try { await api(endpoint, { method: 'POST', body: JSON.stringify({ active: !active }) }); notice = `${label} ${active ? 'hidden from' : 'restored to'} the student experience.`; await load(); } catch (e) { error = e instanceof Error ? e.message : 'Could not update configuration.'; } finally { busy = ''; } }
  async function assignRank() { if (!rankAssignment.studentId || !rankAssignment.rankId) return; await create(`/api/portal-admin/students/${rankAssignment.studentId}/rank`, { rankId: Number(rankAssignment.rankId), awardedDate: rankAssignment.awardedDate || null, notes: rankAssignment.notes.trim() || null }, 'Rank history updated for the student.', () => { rankAssignment = { ...rankAssignment, notes: '' }; }); }
  onMount(load);
</script>
<svelte:head><title>Staff · Portal configuration | Task Karate</title></svelte:head>
<div class="toolbar"><div><span class="eyebrow">ADMINISTRATION</span><h2>Portal configuration</h2><p class="muted">This is the library of definitions used by the student hub—not a second student or class database. Changes are written to the same portal database used by the student hub.</p></div><button class="button secondary" type="button" on:click={load} disabled={loading}>Refresh configuration</button></div>
{#if error}<div class="error" role="alert">{error}</div>{/if}{#if notice}<div class="status" role="status">{notice}</div>{/if}
{#if loading}<section class="card"><p class="muted">Loading portal configuration…</p></section>{:else}<section class="card detail-callout"><span class="eyebrow">WHAT THIS PAGE CONTROLS</span><h3>Definitions, not day-to-day records</h3><p>Use this page to maintain the reusable achievement, mission, and belt/rank definitions that other parts of the portal reference. Student profiles, class schedules, attendance, and billing are managed in their own work areas.</p><div class="configuration-explainer-grid"><div><strong>Achievements</strong><small>Milestone definitions students can earn.</small></div><div><strong>Training missions</strong><small>Practice prompts shown in the student experience.</small></div><div><strong>Ranks</strong><small>Belt definitions and append-only promotion history.</small></div></div></section><div class="configuration-grid"><section class="card"><div class="section-heading"><div><span class="eyebrow">ACHIEVEMENTS</span><h3>Student achievement definitions</h3><p class="muted">Automatic milestone code can award matching names. Keep definitions stable once students have earned them.</p></div><span class="pill">{achievements.length}</span></div><form class="form-grid admin-config-form" on:submit|preventDefault={() => create('/api/portal-admin/configuration/achievements', achievementForm, 'Achievement definition created.', () => { achievementForm = { name: '', description: '', iconName: 'star' }; })}><label>Name<input bind:value={achievementForm.name} maxlength="160" required placeholder="e.g. First tournament" /></label><label>Icon key<input bind:value={achievementForm.iconName} maxlength="80" required /></label><label class="full">Description<textarea bind:value={achievementForm.description} maxlength="2000" required rows="2"></textarea></label><div class="full"><button class="button" disabled={busy.includes('achievements') || !achievementForm.name.trim()}>{busy.includes('achievements') ? 'Saving…' : 'Add achievement'}</button></div></form><div class="config-list">{#each achievements as item}<article class:inactive={!item.isActive} class="config-row"><div><strong>{item.name}</strong><small>{item.description} · {item.awardCount} awarded · icon {item.iconName}</small></div><button class="button secondary small-button" type="button" disabled={busy.includes(`/achievements/${item.achievementId}`)} on:click={() => toggle(`/api/portal-admin/configuration/achievements/${item.achievementId}/active`, item.isActive, item.name)}>{item.isActive ? 'Hide' : 'Restore'}</button></article>{/each}</div></section><section class="card"><div class="section-heading"><div><span class="eyebrow">TRAINING MISSIONS</span><h3>Mission library</h3><p class="muted">Active missions appear in the student training experience and retain completion history when hidden.</p></div><span class="pill">{missions.length}</span></div><form class="form-grid admin-config-form" on:submit|preventDefault={() => create('/api/portal-admin/configuration/missions', missionForm, 'Training mission created.', () => { missionForm = { title: '', description: '', category: 'Training' }; })}><label>Title<input bind:value={missionForm.title} maxlength="160" required placeholder="e.g. Practice front stance" /></label><label>Category<input bind:value={missionForm.category} maxlength="80" required /></label><label class="full">Description<textarea bind:value={missionForm.description} maxlength="2000" required rows="2"></textarea></label><div class="full"><button class="button" disabled={busy.includes('missions') || !missionForm.title.trim()}>{busy.includes('missions') ? 'Saving…' : 'Add mission'}</button></div></form><div class="config-list">{#each missions as item}<article class:inactive={!item.isActive} class="config-row"><div><strong>{item.title}</strong><small>{item.category} · {item.completionCount} completions · {item.description}</small></div><button class="button secondary small-button" type="button" disabled={busy.includes(`/missions/${item.missionId}`)} on:click={() => toggle(`/api/portal-admin/configuration/missions/${item.missionId}/active`, item.isActive, item.title)}>{item.isActive ? 'Hide' : 'Restore'}</button></article>{/each}</div></section></div><div class="configuration-grid"><section class="card"><div class="section-heading"><div><span class="eyebrow">RANK SYSTEM</span><h3>Belt and rank definitions</h3><p class="muted">Rank history is append-only. Assignments create a new historical record rather than overwriting the student’s past.</p></div><span class="pill">{ranks.length}</span></div><form class="form-grid admin-config-form" on:submit|preventDefault={() => create('/api/portal-admin/configuration/ranks', rankForm, 'Rank definition created.', () => { rankForm = { name: '', displayColor: '#d9a245' }; })}><label>Rank name<input bind:value={rankForm.name} maxlength="120" required placeholder="e.g. Purple Belt" /></label><label>Display color<input type="color" bind:value={rankForm.displayColor} /></label><div class="full"><button class="button" disabled={busy.includes('ranks') || !rankForm.name.trim()}>{busy.includes('ranks') ? 'Saving…' : 'Add rank'}</button></div></form><div class="config-list">{#each ranks as item}<article class:inactive={!item.isActive} class="config-row"><div class="config-rank-name"><span style={`background:${item.displayColor ?? '#d9a245'}`}></span><strong>{item.sortOrder}. {item.name}</strong><small>{item.studentCount} current student{item.studentCount === 1 ? '' : 's'}</small></div><button class="button secondary small-button" type="button" disabled={busy.includes(`/ranks/${item.rankId}`)} on:click={() => toggle(`/ranks/${item.rankId}/active`, item.isActive, item.name)}>{item.isActive ? 'Hide' : 'Restore'}</button></article>{/each}</div></section><section class="card"><div class="section-heading"><div><span class="eyebrow">STUDENT PROGRESSION</span><h3>Assign a rank</h3><p class="muted">Use this when an instructor records a promotion. The previous rank remains in history for reporting.</p></div></div><form class="form-grid" on:submit|preventDefault={assignRank}><label class="full">Student<select bind:value={rankAssignment.studentId} required><option value="" disabled>Select student</option>{#each students.filter((student) => student.status === 'active') as student}<option value={student.studentId}>{student.displayName} · {student.rankName ?? 'No rank'}</option>{/each}</select></label><label class="full">New rank<select bind:value={rankAssignment.rankId} required><option value="" disabled>Select rank</option>{#each ranks.filter((rank) => rank.isActive) as rank}<option value={rank.rankId}>{rank.sortOrder}. {rank.name}</option>{/each}</select></label><label>Date<input type="date" bind:value={rankAssignment.awardedDate} required /></label><label class="full">Instructor note<textarea bind:value={rankAssignment.notes} maxlength="500" rows="2" placeholder="Optional promotion context"></textarea></label><div class="full"><button class="button" disabled={busy.includes('/rank') || !rankAssignment.studentId || !rankAssignment.rankId}>{busy.includes('/rank') ? 'Saving…' : 'Record rank promotion'}</button></div></form></section></div><section class="card detail-callout"><span class="eyebrow">MYSTUDIO BOUNDARY</span><h3>Billing remains outside this console</h3><p>Task Karate Portal can display operational membership data when a read-only MyStudio adapter is connected. It does not store cards, run invoices, retry payments, issue refunds, or replace Task-Karate-Web’s manual lead-email workflow.</p><span class="pill">Payments: MyStudio system of record</span></section>{/if}
